public static Common genericFindByField(TableId _tableId, FieldId _fieldId, anytype _value)
{
    DictTable dictTable = new DictTable(_tableId);

    Common common = dictTable.makeRecord();

    select firstonly common
         where common.(_fieldId) == _value;

    return common;
}

public static Common genericFindRecId(TableId _tableId, RecId _recId)
{
    return FTDWorkingWithGenerics::genericFindByField(_tableId, fieldNum(Common, RecId), _recId);
